#!/bin/bash
# Blocks any direct edit of auto-generated compiled files.
# knowledge-bases.ts → edit via clients/{slug}/knowledge-base.md + sync-kb.js
# system-prompt.ts → edit via src/lib/system-prompt.ts only if you understand the risk

INPUT=$(cat)
FILE=$(echo "$INPUT" | python3 -c "import json,sys; print(json.load(sys.stdin).get('tool_input',{}).get('file_path',''))" 2>/dev/null)

if echo "$FILE" | grep -qE "knowledge-bases\.ts$"; then
  echo "🔴 BLOCKED: knowledge-bases.ts is auto-generated by sync-kb.js"
  echo "   Edit the source   : clients/{slug}/knowledge-base.md"
  echo "   Then regenerate  : node scripts/devtools/sync-kb.js --write"
  exit 2
fi

if echo "$FILE" | grep -qE "src/lib/system-prompt\.ts$"; then
  echo "⚠️  WARNING: system-prompt.ts controls the behavior of ALL agents"
  echo "   Any change affects production agents."
  echo "   Confirm the change is intentional and tested."
  exit 1
fi

exit 0
